import type { CreateHost, Host, Message, NodeView, Outcome } from '../host.ts';

const NODES = ['n0', 'n1', 'n2'] as const;
const MAJORITY = 2;

interface NodeState {
  role: NodeView['role'];
  term: number;
  votedFor: string | null;
  votes: Set<string>;
  electionStarted: boolean;
}

const createHost: CreateHost = async () => {
  const nodes = new Map<string, NodeState>();
  for (const id of NODES) {
    nodes.set(id, { role: 'follower', term: 0, votedFor: null, votes: new Set(), electionStarted: false });
  }
  const inTransit = new Map<string, Message>();
  let nextId = 1;

  function send(from: string, to: string, action: string, data: Record<string, unknown>): void {
    const id = `m${nextId++}`;
    inTransit.set(id, { id, from, to, action, data });
  }

  function onRequestVote(self: string, msg: Message): void {
    const n = nodes.get(self)!;
    const candidate = msg.data.from;
    const term = msg.data.term;
    if (typeof candidate !== 'string' || !nodes.has(candidate) || term !== 1) return;
    let granted: boolean;
    if (n.term === 0) {
      n.term = 1;
      n.role = 'follower';
      n.votedFor = candidate;
      granted = true;
    } else {
      granted = n.role === 'follower' && (n.votedFor === null || n.votedFor === candidate);
      if (granted) n.votedFor = candidate;
    }
    send(self, candidate, 'VoteReply', { term: 1, granted });
  }

  function onVoteReply(self: string, msg: Message): void {
    const n = nodes.get(self)!;
    if (n.role !== 'candidate' || msg.data.term !== n.term || msg.data.granted !== true) return;
    n.votes.add(msg.from);
    if (n.votes.size >= MAJORITY) n.role = 'leader';
  }

  function process(msg: Message): void {
    if (msg.action === 'RequestVote') onRequestVote(msg.to, msg);
    else if (msg.action === 'VoteReply') onVoteReply(msg.to, msg);
  }

  const copy = (m: Message): Message => ({ ...m, data: { ...m.data } });

  const host: Host = {
    async inFlight() {
      return [...inTransit.values()].map(copy);
    },
    async deliver(id: string) {
      const msg = inTransit.get(id);
      if (!msg) throw new Error(`no message in transit with id ${id}`);
      inTransit.delete(id);
      process(msg);
    },
    async deliverAll() {
      while (inTransit.size > 0) {
        const [id, msg] = inTransit.entries().next().value!;
        inTransit.delete(id);
        process(msg);
      }
    },
    async timeout(node: string): Promise<Outcome> {
      const n = nodes.get(node);
      if (!n) return { ok: false, reason: `unknown node ${node}` };
      if (n.electionStarted) return { ok: false, reason: `${node} has already started an election` };
      if (n.role !== 'follower' || n.term !== 0) {
        return { ok: false, reason: `${node} is not a follower in term 0` };
      }
      n.electionStarted = true;
      n.role = 'candidate';
      n.term = 1;
      n.votedFor = node;
      n.votes = new Set([node]);
      for (const other of NODES) {
        if (other !== node) send(node, other, 'RequestVote', { from: node, term: 1 });
      }
      return { ok: true };
    },
    async node(node: string) {
      const n = nodes.get(node);
      if (!n) return null;
      return { role: n.role, term: n.term, votedFor: n.votedFor };
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('basic election', async () => {
  const h = await create();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('x'), null);
  assert.equal((await h.timeout('x')).ok, false);
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  const f = await h.inFlight();
  assert.equal(f.length, 2);
  assert.deepEqual(f[0].data, { from: 'n0', term: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('random orders: safety', async () => {
  let seed = 7;
  const rnd = (k: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % k; };
  for (let i = 0; i < 3000; i++) {
    const h = await create();
    const ids = ['n0', 'n1', 'n2'];
    const pending = ids.filter(() => rnd(2) === 0);
    for (;;) {
      const f = await h.inFlight();
      const opts = f.length + pending.length;
      if (opts === 0) break;
      const c = rnd(opts);
      if (c < pending.length) { await h.timeout(pending.splice(c, 1)[0]); }
      else await h.deliver(f[c - pending.length].id);
    }
    const views = await Promise.all(ids.map((n) => h.node(n)));
    const leaders = ids.filter((_, j) => views[j]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
  }
});
EOF
