test('random orders: safety', async () => {
  let seed = 7;
  const rnd = (k: number) => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed % k;
  };
  for (let i = 0; i < 3000; i++) {
    const h = await create();
    const ids = ['n0', 'n1', 'n2'];
    const pending = ids.filter(() => rnd(2) === 0);
    for (;;) {
      const f = await h.inFlight();
      const opts = f.length + pending.length;
      if (opts === 0) break;
      const c = rnd(opts);
      if (c < pending.length) await h.timeout(pending.splice(c, 1)[0]);
      else await h.deliver(f[c - pending.length].id);
    }
    const views = await Promise.all(ids.map((n) => h.node(n)));
    const leaders = ids.filter((_, j) => views[j]!.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const l of leaders) {
      assert.ok(views.filter((v) => v!.votedFor === l).length >= 2);
      for (const v of views) assert.equal(v!.leader, l);
    }
    for (const v of views) if (v!.leader) assert.equal(v!.leader, leaders[0]);
  }
});

