    async giveUp(node: string): Promise<Outcome> {
      const n = nodes.get(node);
      if (!n) return { ok: false, reason: `unknown node ${node}` };
      if (n.role !== 'candidate') return { ok: false, reason: `${node} is not a candidate` };
      // Keeps votedFor = itself, so it grants no other vote this term; later VoteReplies are ignored.
      n.role = 'follower';
      return { ok: true };
    },
    async crash(node: string): Promise<Outcome> {
      const n = nodes.get(node);
      if (!n) return { ok: false, reason: `unknown node ${node}` };
      if (n.role === 'down') return { ok: false, reason: `${node} is already down` };
      // term, votedFor and leader are kept: they survive the crash.
      n.role = 'down';
      n.votes = new Set();
      return { ok: true };
    },
    async recover(node: string): Promise<Outcome> {
      const n = nodes.get(node);
      if (!n) return { ok: false, reason: `unknown node ${node}` };
      if (n.role !== 'down') return { ok: false, reason: `${node} is not down` };
      n.role = 'follower';
      return { ok: true };
    },
    async node(node: string) {
      const n = nodes.get(node);
      if (!n) return null;
      return { role: n.role, term: n.term, votedFor: n.votedFor, leader: n.leader };
    },
  };
  return host;
};

