test('leader announcement: term-0 node joins without voting, candidate steps down', async () => {
  const h = await create();
  await h.timeout('n0');
  await h.timeout('n1');
  // deliver only n0 -> n2 RequestVote, then n2's reply to n0
  let f = await h.inFlight();
  await h.deliver(f.find((m) => m.from === 'n0' && m.to === 'n2')!.id);
  f = await h.inFlight();
  await h.deliver(f.find((m) => m.action === 'VoteReply')!.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  f = await h.inFlight();
  const leaderMsgs = f.filter((m) => m.action === 'Leader');
  assert.equal(leaderMsgs.length, 2);
  assert.deepEqual(leaderMsgs[0].data, { from: 'n0', term: 1 });
  await h.deliver(leaderMsgs.find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });

  const h2 = await create();
  await h2.timeout('n0');
  await h2.deliver((await h2.inFlight()).find((m) => m.to === 'n1')!.id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h2.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h2.timeout('n2')).ok, false);
});

test('giveUp', async () => {
  const h = await create();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('x')).ok, false);
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.timeout('n1');
  await h.deliverAll();
  // n0's late VoteReplies were ignored; n1 got n2's vote (n2 in term 0 voted for whoever came first)
  const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
  assert.equal(views[0]!.role, 'follower');
  assert.equal(views[0]!.votedFor, 'n0');
