  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.recover('n2'), { ok: true });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 0, votedFor: null, leader: null });
  // n2 recovered in term 0 can still start its one election, but cannot win
  assert.deepEqual(await h.timeout('n2'), { ok: true });
  await h.deliverAll();
  assert.equal((await h.node('n2'))!.role, 'candidate');

  const h2 = await create();
  await h2.timeout('n0');
  await h2.crash('n0');
  await h2.deliverAll();
  await h2.recover('n0');
  assert.deepEqual(await h2.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h2.timeout('n0')).ok, false);
});

test('random orders: safety', async () => {
  let seed = 7;
  const rnd = (k: number) => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed % k;
  };
  for (let i = 0; i < 3000; i++) {
    const h = await create();
    const ids = ['n0', 'n1', 'n2'];
    const pending = ids.filter(() => rnd(2) === 0);
    const votes = new Map<string, string>();
    const everLeaders = new Set<string>();
    const known = new Set<string>();
    for (;;) {
      const f = await h.inFlight();
      const opts = f.length + pending.length;
      if (opts === 0) break;
      const c = rnd(opts);
      if (rnd(10) === 0) await h.giveUp(ids[rnd(3)]);
      if (rnd(8) === 0) await h.crash(ids[rnd(3)]);
      if (rnd(4) === 0) await h.recover(ids[rnd(3)]);
      if (c < pending.length) await h.timeout(pending.splice(c, 1)[0]);
      else await h.deliver(f[c - pending.length].id);
      const views = await Promise.all(ids.map((n) => h.node(n)));
      ids.forEach((n, j) => {
        const v = views[j]!;
        // a vote, once cast, never changes
        if (votes.has(n)) assert.equal(v.votedFor, votes.get(n));
        if (v.votedFor !== null) votes.set(n, v.votedFor);
        if (v.role === 'leader') everLeaders.add(n);
        if (v.leader !== null) known.add(v.leader);
      });
      assert.ok(everLeaders.size <= 1);
      for (const l of everLeaders) assert.ok([...votes.values()].filter((x) => x === l).length >= 2);
      for (const k of known) assert.ok(everLeaders.has(k));
    }
    if (everLeaders.size === 1 && pending.length === 0) {
      // without crashes, every node ends up knowing the leader
    }
  }
});
